{
  "system": "notes",
  "rules": [
    "Citations are given in numbered endnotes or footnotes without a terminal full stop unless punctuation is present.",
    "Books are cited: Author, Title in Italics (Editor ed, Publisher Year) Pinpoint Page Range.",
    "Journal articles are cited: Author, ‘Article Title in Single Quotation Marks’ (Year) Volume Journal Name in Italics Starting Page, Pinpoint Page Range.",
    "Book chapters in edited collections are cited: Author, ‘Chapter Title in Single Quotation Marks’ in Editor (ed), Book Title in Italics (Publisher Year) Page Range.",
    "Subsequent citations use the author surname followed by a cross-reference to the first note in parentheses (eg 'Author (n 1)') followed by pinpoint page numbers.",
    "Immediate repetitions of the same source use 'ibid' (in lower case, unitalicised) followed by the pinpoint page number.",
    "Multiple citations within a single note are separated by a semicolon (eg '; see eg ')."
  ],
  "examples": [
    {
      "kind": "book-first",
      "text": "Invented Author, A Made-Up Treatise (Sample Editor ed, Sample University Press 1996) 88–9."
    },
    {
      "kind": "book-first",
      "text": "Invented Author, A Made-Up Treatise (Sample Editor ed, Sample University Press 1996) 101–4."
    },
    {
      "kind": "book-first",
      "text": "Invented Author, A Made-Up Treatise (Sample Editor ed, Sample University Press 1996) 210–15."
    },
    {
      "kind": "book-later",
      "text": "Author (n 1) 201–9"
    },
    {
      "kind": "article-first",
      "text": "Fictional Writer, ‘The Organisation of Liberty’ (2001) 12 Journal of Examples 123, 130–34."
    },
    {
      "kind": "article-later",
      "text": "Writer (n 3) 125–6"
    },
    {
      "kind": "chapter-first",
      "text": "Another Person, ‘A Further Invented Title’ in Sample Editor (ed), A Collection of Examples (Sample University Press 2010) 310–45."
    },
    {
      "kind": "edited-or-translated",
      "text": "Invented Author, A Made-Up Treatise (Sample Editor ed, Sample University Press 1996) 88–9."
    },
    {
      "kind": "ibid",
      "text": "ibid 90."
    },
    {
      "kind": "ibid",
      "text": "ibid 127."
    },
    {
      "kind": "ibid",
      "text": "ibid 112."
    },
    {
      "kind": "ibid",
      "text": "ibid 214."
    },
    {
      "kind": "cross-reference",
      "text": "Author (n 1) 201–9; see eg Writer (n 3) 125–6."
    }
  ]
}

